'use strict';

const DB=window.CLOCKED_DATA;
// Browser never receives the Clocked API key. Requests use the Vercel server function.
let liveRequestId=0;
const $=id=>document.getElementById(id);
const OFFERS=[...DB.incident_offers,...DB.service_offers];
const stop=new Set('a an the i my me we our and to for on in is it does not please help need want with get of from about would should am are can you could have has that this it an new issue request service laptop computer software hardware'.split(' '));
const sampleTickets=[
 {id:'INC1042',user:'DEMO001',title:'Laptop does not power on',issue:'Dell laptop will not turn on',status:'In Progress',channel:'Service Portal',owner:'Endpoint Support',date:'Nov 9, 2026',note:'Engineer reviewing device diagnostics',kind:'Incident'},
 {id:'INC1031',user:'DEMO001',title:'Outlook keeps crashing',issue:'My Outlook keeps crashing',status:'Open',channel:'Chatbot',owner:'Application Support',date:'Nov 8, 2026',note:'Awaiting agent triage',kind:'Incident'},
 {id:'REQ2048',user:'DEMO001',title:'Visio installation',issue:'I need Microsoft Visio installed',status:'Awaiting Approval',channel:'VoiceIQ',owner:'Software Requests',date:'Nov 7, 2026',note:'Manager approval requested',kind:'Service Request'},
 {id:'INC1048',user:'DEMO002',title:'VPN will not connect',issue:'The VPN is no longer connecting',status:'Open',channel:'Live Chat',owner:'Network Support',date:'Nov 10, 2026',note:'Network team reviewing connection logs',kind:'Incident'}
];
const MODULES=[
 {id:'tickets',icon:'▤',title:'Ticket Management',detail:'Types, offerings, fields, routing and existing tickets'},
 {id:'assets',icon:'▣',title:'Asset Management',detail:'Device context and asset clarification'},
 {id:'users',icon:'♙',title:'User Management',detail:'Identity, profile, access and entitlements'},
 {id:'voice',icon:'◖',title:'VoiceIQ',detail:'Conversational intake and caller recognition'},
 {id:'knowledge',icon:'▧',title:'Bot Knowledge',detail:'Evidence backed guidance before escalation'},
 {id:'livechat',icon:'◎',title:'Live Chat',detail:'Informed transfer and context handoff'},
 {id:'agent',icon:'⌘',title:'Agent Studio',detail:'Offering quality, catalog testing and ambiguity'},
 {id:'framework',icon:'⧉',title:'Bot Framework',detail:'Shared classification across chat and portal'}
];
const KB=[
 {id:'KB001',name:'Password reset guidance',tags:['password','reset','sign in','login'],desc:'A sample knowledge result for password reset inquiries. The original demo scenario references KB001.'},
 {id:'KB003',name:'VPN troubleshooting',tags:['vpn','network','connecting'],desc:'A sample knowledge result for VPN connectivity questions. Escalate only if the issue persists.'},
 {id:'KB006',name:'Printer paper jam guidance',tags:['printer','paper','jam'],desc:'A sample troubleshooting result for paper jam incidents.'},
 {id:'KB007',name:'Shared drive access',tags:['shared drive','permission','file'],desc:'A sample knowledge result for inaccessible shared drives.'}
];
const initialCase=DB.demo_cases.find(x=>x.case_id==='T003');
const state={page:'overview',userId:'DEMO001',caseId:'T003',utterance:initialCase.user_query,channel:'VoiceIQ',decision:null,step:0,assetId:null,stage:'intro',voiceType:'recognized',voiceNote:'',showAllAssets:false,searchUsers:'',searchCatalog:'',catalogId:'INC001',ticketFilter:'All',feedback:[],apiResult:null,apiStatus:'not-run',tickets:sampleTickets.map(x=>({...x})),navHistory:['overview']};
try{state.feedback=JSON.parse(localStorage.getItem('clocked_p2_feedback')||'[]')}catch(e){state.feedback=[]}
const ICON={user:'♙',asset:'▣',ticket:'▤',voice:'◖',knowledge:'▧',chat:'◎'};
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const tokens=s=>(String(s||'').toLowerCase().match(/[a-z0-9]+/g)||[]).filter(w=>w.length>2&&!stop.has(w));
function user(){return DB.users.find(x=>x.user_id===state.userId)||DB.users[0]}
function owned(){return DB.assets.filter(a=>a.user_id===state.userId)}
function offer(id){return OFFERS.find(o=>o.offering_id===id)}
function typeName(id){return id==='INC'?'Incident':id==='REQ'?'Service Request':'Not selected'}
function mapping(id){return DB.mappings.find(m=>m.offering_id===id&&String(m.is_default)==='true')||DB.mappings.find(m=>m.offering_id===id)}
function cat(id){return DB.categories.find(c=>c.category_id===id)}
function sub(id){return DB.subcategories.find(s=>s.subcategory_id===id)}
function fields(id){return DB.field_rules.filter(f=>f.offering_id===id)}
function getCase(){return DB.demo_cases.find(c=>c.case_id===state.caseId)}
function short(s,n=86){s=String(s||'');return s.length>n?s.slice(0,n-1)+'…':s}
function statusTag(s){return /progress|open/i.test(s)?'good':/await|pending/i.test(s)?'warn':'blue'}
function pageHeader(title,kicker,desc,right=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p class="subtitle">${desc}</p></div>${right}</div>`}
function button(label,action,cls='btn',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function kpi(n,title){return `<div class="stats-card"><div class="stat-value">${n}</div><div class="stat-label">${title}</div></div>`}
function opt(items,value,label,valueKey){return items.map(x=>`<option value="${esc(x[valueKey])}" ${String(x[valueKey])===String(value)?'selected':''}>${esc(x[label])}</option>`).join('')}
function card(title,content,cl=''){return `<section class="card ${cl}"><div class="card-head"><h3>${title}</h3></div>${content}</section>`}
function notice(){return `<p class="footer-note">Proof of concept. All people, assets and catalog records are fictional; all ticket changes and VoiceIQ handoffs remain simulated. In live mode, only intent assessment and offering reranking call the real Clocked API through Vercel. Other decisions remain local demonstrations.</p>`}

function evaluate(utterance,exactCase){
 const q=String(utterance||'').trim();const t=tokens(q);const tset=new Set(t);
 let current=exactCase&&exactCase.user_query.toLowerCase()===q.toLowerCase()?exactCase:null;
 if(!current){current=DB.demo_cases.find(c=>c.user_id===state.userId&&c.user_query.toLowerCase()===q.toLowerCase())||null}
 const scored=OFFERS.map(o=>{const phr=tokens([o.offering_name,o.synonyms,o.description].join(' '));const os=new Set(phr);let s=0;for(const w of tset)if(os.has(w))s+=1;let score=tset.size?s/tset.size:0;if((o.offering_name||'').toLowerCase().includes(q.toLowerCase())&&q.length>5)score+=2;return {o,score}}).sort((a,b)=>b.score-a.score);
 let route=current?.expected_route||'';
 if(!route){if(/capital of|weather today|sports result/i.test(q))route='OUT_OF_SCOPE';else if(/policy|how do i|how to|guide|where is/i.test(q))route='KNOWLEDGE';else if(/agent|live chat|human/i.test(q))route='LIVE_CHAT';else if(/broken|crash|not working|failed|won.t|can't|cannot|down|issue|error|not connecting/i.test(q))route='TICKETING';else if(/need|install|request|access|new|replacement/i.test(q))route='TICKETING';else route='CLARIFY'}
 let selected=current?.expected_offering_id?offer(current.expected_offering_id):null;
 if(!selected&&/TICKETING|LIVE_CHAT|MULTIPLE_INTENTS/.test(route)){selected=scored[0]?.score>0?scored[0].o:null}
 if(selected&&current?.expected_ticket_type&&selected.ticket_type_id!==current.expected_ticket_type){selected=offer(current.expected_offering_id)}
 const candidates=selected?[{o:selected,score:100},...scored.filter(x=>x.o.offering_id!==selected.offering_id).slice(0,2)]:scored.slice(0,3);
 const qlower=q.toLowerCase();const assets=owned().filter(a=>{const name=(a.manufacturer+' '+a.device_type+' '+a.model+' '+a.device_label).toLowerCase();return qlower.includes(a.manufacturer.toLowerCase())||qlower.includes(a.device_type.toLowerCase())||tokens(name).some(w=>tset.has(w))});
 const allAssets=owned();const needsAsset=!!selected&&((selected.asset_policy||'').includes('required')||current?.asset_expected==='conditional')&&/laptop|computer|device|desktop|monitor|printer|battery|hardware/i.test(q);
 const affected=needsAsset?(assets.length?assets:allAssets):[];
 const mm=selected?mapping(selected.offering_id):null;
 const related=state.tickets.filter(x=>x.user===state.userId&&/open|progress|await/i.test(x.status)&&q.length>4).map(ticket=>{
   const ticketTokens=new Set(tokens(ticket.title+' '+ticket.issue));let hits=0;for(const w of tset){if(ticketTokens.has(w))hits++}
   return {ticket,hits,score:tset.size?hits/tset.size:0};
 }).filter(x=>x.hits>0).sort((a,b)=>b.score-a.score);
 let rec='';
 if(route==='OUT_OF_SCOPE')rec='Explain that this request is outside the supported service desk scope.';
 else if(route==='CLARIFY')rec='Ask what the user is trying to accomplish before selecting a ticket type.';
 else if(route==='KNOWLEDGE'||route==='KNOWLEDGE_NO_MATCH')rec='Search relevant knowledge. Do not invent an answer if supporting evidence is missing.';
 else if(route==='MULTIPLE_INTENTS')rec='Separate the incident and the new request, then ask the user which to pursue.';
 else if(needsAsset&&affected.length!==1&&!state.assetId)rec='Ask which of the assigned devices is affected before adding the asset.';
 else if(related.length)rec='Check whether the caller wants to continue an existing ticket or create a new one.';
 else if(route==='LIVE_CHAT')rec='Confirm the issue and prepare a context summary before a simulated agent handoff.';
 else if(selected)rec=`Propose ${typeName(selected.ticket_type_id).toLowerCase()} ${selected.offering_id}, collect required fields, then ask for confirmation.`;
 else rec='Ask a targeted question; no valid catalog choice has been established.';
 return {q,caseId:current?.case_id||null,route,selected,candidates,assets:affected,needsAsset,allAssets,related,mm,cat:mm?cat(mm.category_id):null,sub:mm?sub(mm.subcategory_id):null,fields:selected?fields(selected.offering_id):[],rec,source:current?'Existing expected test case':'Illustrative text matching',channel:state.channel};
}
async function doEvaluate(){
 state.decision=evaluate(state.utterance,getCase());state.step=0;state.assetId=null;
 state.apiResult=null;state.apiStatus='pending';render();
 const id=++liveRequestId;
 
 const choices=state.decision.candidates.filter(x=>x.o).map(x=>({id:x.o.offering_id,title:x.o.offering_name,text:String(x.o.description||'')+' '+String(x.o.synonyms||'')})).slice(0,8);
 // Always present a real, bounded catalog to the SDK; never fabricate an API decision.
 if(!choices.length){state.apiStatus='no-candidates';render();return}
 try{
  const resp=await fetch('/api/clocked',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({utterance:state.utterance,candidates:choices})});
  const result=await resp.json();if(id!==liveRequestId)return;
  if(!resp.ok){state.apiStatus='error';state.apiResult={error:result.error||('HTTP '+resp.status)};render();return}
  state.apiResult=result;state.apiStatus='live';
  // Apply an API choice only if it belongs to the validated shortlist. Preserve local catalog ownership.
  const matching=(result.offerings||[]).find(x=>x.action==='use'&&Number(x.relevance_score)>=.36&&choices.some(o=>o.id===x.id));
  if(matching){const selected=offer(matching.id);const mm=mapping(matching.id);state.decision.selected=selected;state.decision.mm=mm;state.decision.cat=mm?cat(mm.category_id):null;state.decision.sub=mm?sub(mm.subcategory_id):null;state.decision.fields=fields(matching.id);state.decision.source='Real Clocked rerank with local catalog validation';state.decision.rec=`Clocked ranked ${selected.offering_id} as relevant. Validate mandatory fields, assets, existing tickets, and user confirmation before an action.`}
  render();notify('Real Clocked API results received');
 }catch(e){if(id!==liveRequestId)return;state.apiStatus='error';state.apiResult={error:'Network or server connection failed'};render()}
}
function go(page){state.page=page;state.navHistory.push(page);render();window.scrollTo({top:0,behavior:'instant'})}
function notify(message){const e=$('toast');e.textContent=message;e.classList.add('show');clearTimeout(notify.handle);notify.handle=setTimeout(()=>e.classList.remove('show'),3000)}
function render(){const names={overview:'Overview',studio:'Decision Studio',voice:'VoiceIQ Simulator',tickets:'Ticket Management',assets:'Asset Management',users:'User Management',knowledge:'Bot Knowledge',livechat:'Live Chat',agent:'Agent Studio',framework:'Bot Framework',feedback:'Feedback'};
 document.title=`Clocked Studio | ${names[state.page]}`;
 $('crumb').textContent=names[state.page];
 document.querySelectorAll('.nav-item').forEach(b=>{const on=b.dataset.page===state.page;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 const renderers={overview:renderOverview,studio:renderStudio,voice:renderVoice,tickets:renderTickets,assets:renderAssets,users:renderUsers,knowledge:renderKnowledge,livechat:renderLivechat,agent:renderAgent,framework:renderFramework,feedback:renderFeedback};
 $('main').innerHTML=renderers[state.page]();renderInspector();
}

function renderOverview(){const tiles=MODULES.map(m=>`<button class="module-tile" data-go="${m.id}"><span class="module-icon">${m.icon}</span><strong>${m.title}</strong><small>${m.detail}</small></button>`).join('');
 const hit=state.decision;
 return `<div class="hero"><div class="hero-copy"><div class="eyebrow">THE FUTURE OF SERVICE INTELLIGENCE</div><h1>One brain.<br>Every service decision.</h1><p>Clocked is the shared intelligence layer across the service ecosystem. Explore how a single user request becomes an explainable, validated next action across modules.</p>${button('Explore Decision Studio →','to-studio')} ${button('Try VoiceIQ scenario','to-voice','btn secondary')}</div><div class="hero-orb" aria-hidden="true"><span>✳</span></div></div>
 <div class="grid cols4">${kpi(DB.users.length,'Synthetic user profiles')}${kpi(DB.assets.length,'Assigned assets')}${kpi(OFFERS.length,'Service and incident offerings')}${kpi(DB.demo_cases.length,'Reference test scenarios')}</div>
 <div class="section-row"><div><h2>One ecosystem, one decision engine</h2><p>Choose any module and continue with the same selected user and catalog.</p></div><span class="pill blue">Unified synthetic data</span></div>
 <div class="grid cols4">${tiles}</div>
 <div class="section-row"><div><h2>How Clocked connects the journey</h2><p>Explore the visible evidence and final recommendation.</p></div>${button('Open walkthrough','to-studio','btn sm')}</div>
 <section class="card"><div class="workflow"><span class="workflow-step">Voice or chat</span><span class="workflow-arrow">→</span><span class="workflow-step">User context</span><span class="workflow-arrow">→</span><span class="workflow-step active">Clocked evaluates</span><span class="workflow-arrow">→</span><span class="workflow-step">Catalog & assets</span><span class="workflow-arrow">→</span><span class="workflow-step">Confirm action</span></div><div class="blue-line"></div><div class="grid cols2"><div><h3>Try the Dell ambiguity case</h3><p>DEMO001 says “My Dell computer is broken.” Clocked sees three Dell assets and should request clarification rather than guessing.</p><div class="action-row">${button('Inspect case T003','open-t003','btn sm')}</div></div><div><h3>Try a returning caller</h3><p>See how VoiceIQ could offer to continue a ticket from the service portal or start a new request without losing the shared context.</p><div class="action-row">${button('Simulate call','voice-existing','btn secondary sm')}</div></div></div></section>${notice()}`}

function renderStudio(){const d=state.decision;const c=getCase();
 const choices=DB.demo_cases.map(x=>`<option value="${x.case_id}" ${x.case_id===state.caseId?'selected':''}>${x.case_id} · ${esc(short(x.user_query,57))}</option>`).join('');
 const users=DB.users.slice(0,200).map(x=>`<option value="${x.user_id}" ${x.user_id===state.userId?'selected':''}>${x.user_id} · ${esc(x.display_name)}</option>`).join('');
 let content='';if(d){const tabs=['Understand','Compare','Validate','Recommend'];const offerRecord=d.selected;const alternative=d.candidates.slice(1);const base=`<div class="stepper">${tabs.map((t,i)=>`<button type="button" class="step-pill ${state.step===i?'active':''}" data-step="${i}">${i+1}. ${t}</button>`).join('')}</div>`;
  let body='';if(state.step===0){body=`<div class="grid cols2"><div class="flow-card"><strong>Request observed</strong><p>${esc(d.q)}</p><span class="flow-stamp">CHANNEL · ${esc(d.channel)}</span></div><div class="flow-card"><strong>Context loaded</strong><p>${esc(user().display_name)} · ${esc(user().department)} · ${esc(user().location)}</p><span class="flow-stamp">SOURCE · USERS · ${esc(state.userId)}</span></div></div><div class="note">Clocked treats the user's words as the starting point, then consults configured descriptions, fields and permitted relationships. This is a predefined demonstration, not a display of hidden model reasoning.</div>`}
  else if(state.step===1){body=`<div class="grid cols2"><div class="flow-card"><strong>Selected path</strong><p><span class="pill blue">${esc(d.route)}</span></p><p style="margin-top:10px">${d.selected?`Candidate offering: <b>${esc(d.selected.offering_id)} · ${esc(d.selected.offering_name)}</b>`:'No confirmed offering yet.'}</p><span class="flow-stamp">${esc(d.source)}</span></div><div class="flow-card"><strong>Alternative candidates</strong><div class="list">${alternative.length?alternative.map(x=>`<div class="tiny">${esc(x.o.offering_id)} · ${esc(x.o.offering_name)}</div>`).join(''):'No comparable configured candidates in this step.'}</div></div></div><div class="note">The chosen offering follows the existing test case where one is provided. Alternatives use illustrative keyword comparison, not real model confidence scores.</div>`}
  else if(state.step===2){body=`<div class="grid cols2"><div><h3>Catalog validation</h3><dl class="kv"><dt>Ticket type</dt><dd>${esc(typeName(d.selected?.ticket_type_id))}</dd><dt>Offering</dt><dd>${esc(d.selected?.offering_id||'Unselected')}</dd><dt>Category</dt><dd>${esc(d.cat?.category_name||'Not selected')}</dd><dt>Subcategory</dt><dd>${esc(d.sub?.subcategory_name||'Not selected')}</dd><dt>Required fields</dt><dd>${esc(d.fields.filter(f=>String(f.required)==='true').map(f=>f.field_label).join(', ')||'Based on offering')}</dd></dl></div><div><h3>Relevant assigned assets</h3><div class="list">${d.assets.length?d.assets.map(a=>`<button type="button" class="row-card clickable ${state.assetId===a.asset_id?'selected':''}" data-asset="${a.asset_id}"><div><h4>${esc(a.manufacturer+' '+a.model)}</h4><p>${esc(a.asset_id+' · '+a.device_type+' · '+a.device_label)}</p></div><span>→</span></button>`).join(''):'<div class="note">No asset required for this request, or no matching asset found.</div>'}</div></div></div>${d.related.length?`<div class="note amber" style="margin-top:12px">Illustrative cross channel ticket matches: ${d.related.map(x=>esc(x.ticket.id+' ('+x.ticket.channel+')')).join(', ')}. These are mock ticket records, not imported workbook rows.</div>`:''}`}
  else{body=`<div class="result-head"><div class="result-icon">✓</div><div><h3>Recommended next action</h3><div class="tiny">Explained from the available demo facts</div></div></div><div class="decision-quote">${esc(d.rec)}</div><div class="action-row">${button('Simulate in VoiceIQ','voice-current','btn sm')}${button('Inspect ticket catalog','to-tickets','btn secondary sm')}${button('Run another scenario','reset-decision','btn ghost sm')}</div>`}
 content=`<section class="card"><div class="card-head"><h3>Clocked decision journey</h3><span class="pill blue">${esc(d.caseId||'CUSTOM INPUT')}</span></div>${base}${body}<div class="action-row">${state.step>0?button('← Previous','previous-step','btn ghost sm'):''}${state.step<3?button('Next decision →','next-step','btn sm'):''}</div></section>`
 }else content=`<section class="card"><div class="empty"><strong>Run a scenario to see Clocked's decision journey</strong>Input from the shared data will be evaluated against the configured catalog and user context.</div></section>`;
 return `${pageHeader('Decision Studio','CENTRAL INTELLIGENCE','Review the request, candidate offerings, owned assets, valid catalog hierarchy, existing tickets and next action. Every step identifies the evidence it uses.','<span class="pill purple">Evidence view</span>')}
 <section class="card" style="margin-bottom:17px"><div class="card-head"><h3>Scenario workspace</h3><span class="pill">${state.apiStatus==='live'?'Real Clocked API':state.apiStatus==='pending'?'Contacting Clocked':'API not yet verified'}</span></div><div class="grid cols3"><div class="formfield"><label for="scenario">Reference case</label><select class="field" id="scenario">${choices}</select></div><div class="formfield"><label for="demo-user">Synthetic user</label><select class="field" id="demo-user">${users}</select></div><div class="formfield"><label for="channel">Entry channel</label><select class="field" id="channel">${['VoiceIQ','Chatbot','Service Portal','Live Chat'].map(x=>`<option ${x===state.channel?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="formfield" style="margin-top:16px"><label for="utterance">What does the user say?</label><textarea class="field" id="utterance" rows="2">${esc(state.utterance)}</textarea></div><div class="action-row">${button('✳ Run Clocked Decision','run-decision')}${button('Reset to T003','open-t003','btn ghost')}</div><p class="tiny" style="margin-top:10px">The inspector separates real API calls from local decision criteria. All operational actions remain simulated.</p></section>
 ${content}${notice()}`}

function renderTickets(){const records=state.tickets.filter(x=>state.ticketFilter==='All'||x.status===state.ticketFilter);const d=state.decision;const mm=d?.selected?mapping(d.selected.offering_id):null;
 return `${pageHeader('Ticket Management','SERVICE OPERATIONS','Ticket creation is governed by configured types, offerings, category relationships, mandatory fields and existing ticket checks.','<span class="pill">Simulated tickets</span>')}
 <div class="grid cols4" style="margin-bottom:18px">${kpi('2','Supported ticket types')}${kpi(OFFERS.length,'Active catalog options')}${kpi(DB.mappings.length,'Valid catalog relationships')}${kpi(state.tickets.length,'Illustrative tickets')}</div>
 <div class="grid cols2"><section class="card"><div class="card-head"><h3>Selected catalog classification</h3>${button('Test utterance','to-studio','btn ghost sm')}</div>${d?.selected?`<dl class="kv"><dt>Type</dt><dd>${typeName(d.selected.ticket_type_id)}</dd><dt>Offering</dt><dd>${esc(d.selected.offering_id+' · '+d.selected.offering_name)}</dd><dt>Category</dt><dd>${esc(d.cat?.category_name||'Not mapped')}</dd><dt>Subcategory</dt><dd>${esc(d.sub?.subcategory_name||'Not mapped')}</dd><dt>Asset rule</dt><dd>${esc(d.selected.asset_policy)}</dd></dl>`:`<div class="empty">Run a scenario in Decision Studio to populate the selected ticket mapping.</div>`}</section><section class="card"><div class="card-head"><h3>Required field decisions</h3><span class="pill blue">From offering rules</span></div>${d?.selected?`<div class="list">${d.fields.map(f=>`<div class="row-card"><div><h4>${esc(f.field_label)}</h4><p>${esc(f.ask_when||'')}</p></div><span class="tag ${String(f.required)==='true'?'warn':''}">${String(f.required)==='true'?'Required':'Conditional'}</span></div>`).join('')||'<div class="tiny">No explicit field requirement.</div>'}</div>`:'<p>Clocked checks the required fields for the configured offering and asks only for missing information.</p>'}</section></div>
 <section class="card" style="margin-top:17px"><div class="card-head"><h3>Tickets visible to Clocked</h3><select id="ticket-filter" class="field" style="max-width:185px"><option>All</option>${['Open','In Progress','Awaiting Approval'].map(s=>`<option ${state.ticketFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ticket</th><th>Issue</th><th>User</th><th>Created in</th><th>Status</th><th>Owner</th></tr></thead><tbody>${records.map(t=>`<tr><td><strong>${esc(t.id)}</strong><br><small>${esc(t.kind)}</small></td><td>${esc(t.title)}</td><td>${esc(t.user)}</td><td>${esc(t.channel)}</td><td><span class="tag ${statusTag(t.status)}">${esc(t.status)}</span></td><td>${esc(t.owner)}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:14px">Ticket records in this view are illustrative additions for the concept. They demonstrate cross channel matching and do not represent production tickets or existing rows in the original workbook.</div></section>${notice()}`}

function renderAssets(){const ownedSet=state.showAllAssets?DB.assets:owned();return `${pageHeader('Asset Management','CONTEXTUAL SERVICE INTELLIGENCE','Clocked uses the asset inventory to clarify which real device the user means, but it never requires an asset for an unrelated request.','<span class="pill blue">Same user context</span>')}
 <div class="card" style="margin-bottom:18px"><div class="card-head"><h3>Asset lookup</h3>${button(state.showAllAssets?'Show selected user only':'Show all assets', 'toggle-assets','btn ghost sm')}</div><div class="grid cols2"><div class="formfield"><label>Selected user</label><select id="asset-user" class="field">${DB.users.map(u=>`<option value="${u.user_id}" ${u.user_id===state.userId?'selected':''}>${esc(u.user_id+' · '+u.display_name)}</option>`).join('')}</select></div><div class="formfield"><label>Detected issue</label><input class="field" value="${esc(short(state.utterance,75))}" readonly></div></div></div>
 <div class="grid cols3">${ownedSet.slice(0,state.showAllAssets?60:100).map(a=>`<div class="card" style="padding:18px"><div class="card-head"><div class="module-icon">${/Laptop/i.test(a.device_type)?'▰':'▣'}</div><span class="tag ${a.status==='Active'?'good':''}">${esc(a.status)}</span></div><h3>${esc(a.manufacturer+' '+a.model)}</h3><p class="tiny" style="margin:7px 0">${esc(a.device_label)}</p><dl class="kv"><dt>Asset ID</dt><dd>${esc(a.asset_id)}</dd><dt>Type</dt><dd>${esc(a.device_type)}</dd><dt>Assigned to</dt><dd>${esc(a.user_id)}</dd><dt>Location</dt><dd>${esc(a.location)}</dd></dl>${button(state.assetId===a.asset_id?'Selected ✓':'Select for scenario','asset:'+a.asset_id,'btn secondary sm')}</div>`).join('')}</div>${state.showAllAssets?'<p class="tiny" style="margin-top:10px">Showing the first 60 of 200 dataset assets.</p>':''}${notice()}`}

function renderUsers(){const needle=state.searchUsers.toLowerCase();const records=DB.users.filter(x=>Object.values(x).some(v=>String(v??'').toLowerCase().includes(needle)));return `${pageHeader('User Management','IDENTITY AND PERSONALIZATION','The selected identity and permissions inform every scenario. VoiceIQ may recognize a registered phone, but sensitive actions still require appropriate verification.','<span class="pill">200 fictional profiles</span>')}
 <section class="card"><div class="card-head"><h3>Shared user directory</h3><div class="inline-form"><input id="user-search" class="field" placeholder="Search ID, name or department" value="${esc(state.searchUsers)}" style="min-width:210px">${button('Find','find-users','btn secondary sm')}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>User ID</th><th>Display name</th><th>Department</th><th>Location</th><th>Assets</th><th>Status</th></tr></thead><tbody>${records.slice(0,35).map(u=>`<tr class="${u.user_id===state.userId?'sel':''}" data-user-row="${u.user_id}"><td><strong>${esc(u.user_id)}</strong></td><td>${esc(u.display_name)}</td><td>${esc(u.department)}</td><td>${esc(u.location)}</td><td>${DB.assets.filter(a=>a.user_id===u.user_id).length}</td><td><span class="tag good">${esc(u.status)}</span></td></tr>`).join('')}</tbody></table></div><p class="tiny" style="margin-top:12px">Showing ${Math.min(records.length,35)} of ${records.length} matching users. Click a user to apply the same identity throughout the prototype.</p></section>${notice()}`}

function renderKnowledge(){const q=String(state.utterance||'').toLowerCase();const matches=KB.filter(k=>k.tags.some(w=>q.includes(w)));return `${pageHeader('Bot Knowledge','EVIDENCE BEFORE ACTION','Knowledge can support resolution without opening a ticket. An asset should only be requested if the selected workflow needs it.','<span class="pill purple">Knowledge evidence</span>')}
 <div class="grid cols2"><section class="card"><div class="card-head"><h3>Illustrative knowledge catalog</h3><span class="pill">Example entries</span></div><div class="list">${KB.map(k=>`<div class="row-card"><div><h4>${esc(k.id)} · ${esc(k.name)}</h4><p>${esc(k.desc)}</p></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Current request match</h3>${button('Run scenario','to-studio','btn ghost sm')}</div><div class="decision-quote" style="font-size:14px">${esc(state.utterance)}</div><div style="margin-top:17px">${matches.length?matches.map(k=>`<div class="flow-card"><strong>${esc(k.id+' · '+k.name)}</strong><p>${esc(k.desc)}</p></div>`).join(''):'<div class="note amber">No sample knowledge result matched the current utterance. Clocked should not invent an answer or automatically create a ticket.</div>'}</div><p class="tiny">These summary cards are illustrative placeholders. The full source article bodies are not contained in the imported workbook; the prototype does not claim to validate their content.</p></section></div>${notice()}`}

function renderLivechat(){return `${pageHeader('Live Chat','CONTEXT PRESERVING HANDOFF','Clocked prepares an issue classification and the verified context before an optional transfer to a human. The caller confirms the handoff.','<span class="pill blue">Simulated transfer</span>')}
 <div class="grid cols2"><section class="card"><h3>Context package</h3><dl class="kv"><dt>Requestor</dt><dd>${esc(user().display_name+' ('+state.userId+')')}</dd><dt>Issue</dt><dd>${esc(state.utterance)}</dd><dt>Proposed offering</dt><dd>${esc(state.decision?.selected?.offering_id||'Classification pending')}</dd><dt>Known asset</dt><dd>${esc(state.assetId||'Not confirmed')}</dd><dt>Channel</dt><dd>${esc(state.channel)}</dd></dl><div class="action-row">${button('Simulate handoff','handoff','btn')}${button('Inspect decision','to-studio','btn ghost')}</div></section><section class="card"><h3>Proposed handoff flow</h3><div class="list" style="margin-top:18px"><div class="flow-card"><strong>1. Classify intent</strong><p>Use the same configured ticket and offering catalog.</p></div><div class="flow-card"><strong>2. Confirm caller choice</strong><p>Offer a live agent or an appropriate alternate path.</p></div><div class="flow-card"><strong>3. Pass context</strong><p>Prepare a concise summary, relevant asset, and existing ticket context for the agent.</p></div></div><div class="note">The demo does not contact a real agent, connect Microsoft Teams, or create a persistent ticket.</div></section></div>${notice()}`}

function overlapRows(){const groups=[DB.incident_offers,DB.service_offers];const out=[];
 for(const offers of groups){const shortlist=offers;for(let i=0;i<shortlist.length;i++){const a=shortlist[i],wa=new Set(tokens(a.offering_name+' '+a.synonyms));for(let j=i+1;j<shortlist.length;j++){const b=shortlist[j],wb=new Set(tokens(b.offering_name+' '+b.synonyms));const inter=[...wa].filter(x=>wb.has(x));const denom=new Set([...wa,...wb]).size;const pct=Math.round(100*inter.length/(denom||1));if(pct>=30)out.push({a,b,pct,shared:inter})}}}
 return out.sort((a,b)=>b.pct-a.pct).slice(0,6)}
function renderAgent(){const a=offer(state.catalogId)||OFFERS[0];const mm=mapping(a.offering_id);const records=OFFERS.filter(o=>{const s=(o.offering_id+' '+o.offering_name+' '+o.description).toLowerCase();return s.includes(state.searchCatalog.toLowerCase())}).slice(0,25);const overlap=overlapRows();
 return `${pageHeader('Agent Studio','CATALOG INTELLIGENCE','Test configured descriptions, offerings and valid hierarchies before customers encounter them. Surface overlapping configurations and explain the possible ambiguity.','<span class="pill amber">Concept capability</span>')}
 <div class="grid cols2"><section class="card"><div class="card-head"><h3>Offering Explorer</h3><span class="pill">215 offerings</span></div><div class="inline-form"><input class="field" id="catalog-search" value="${esc(state.searchCatalog)}" placeholder="Search offering or description">${button('Search','search-catalog','btn secondary sm')}</div><div class="list" style="margin-top:13px;max-height:290px;overflow:auto">${records.map(o=>`<button type="button" class="row-card clickable ${o.offering_id===state.catalogId?'selected':''}" data-catalog="${o.offering_id}"><div><h4>${esc(o.offering_id+' · '+o.offering_name)}</h4><p>${esc(typeName(o.ticket_type_id)+' · '+o.domain)}</p></div><span>›</span></button>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Configuration detail</h3><span class="pill blue">${esc(a.offering_id)}</span></div><h3>${esc(a.offering_name)}</h3><p class="tiny" style="margin:10px 0">${esc(a.description)}</p><dl class="kv"><dt>Ticket type</dt><dd>${esc(typeName(a.ticket_type_id))}</dd><dt>Asset policy</dt><dd>${esc(a.asset_policy)}</dd><dt>Category</dt><dd>${esc(cat(mm?.category_id)?.category_name||'Not configured')}</dd><dt>Subcategory</dt><dd>${esc(sub(mm?.subcategory_id)?.subcategory_name||'Not configured')}</dd><dt>Trigger phrases</dt><dd>${esc(a.synonyms)}</dd></dl><div class="note" style="margin-top:10px">Any changes to this configuration would remain suggestions until an administrator approves them. No catalog records are edited by this demo.</div></section></div>
 <section class="card" style="margin-top:18px"><div class="card-head"><h3>Configuration overlap audit</h3><span class="pill amber">Calculated comparison, not AI confidence</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Offering A</th><th>Offering B</th><th>Token overlap</th><th>Shared terms</th></tr></thead><tbody>${overlap.map(r=>`<tr><td>${esc(r.a.offering_id)} · ${esc(short(r.a.offering_name,34))}</td><td>${esc(r.b.offering_id)} · ${esc(short(r.b.offering_name,34))}</td><td><strong>${r.pct}%</strong><div class="fake-bar"><span style="width:${r.pct}%"></span></div></td><td>${esc(r.shared.join(', '))}</td></tr>`).join('')}</tbody></table></div><p class="tiny" style="margin-top:14px">Percentage is a simple comparison of distinct words in the offering names and synonyms. It is not a probability of misclassification, and should not substitute for an intent level audit.</p></section>${notice()}`}

function renderFramework(){return `${pageHeader('Bot Framework','CHANNEL INDEPENDENT INTELLIGENCE','One customer request should receive consistent classification whether it starts in the bot, service portal, VoiceIQ or live chat.','<span class="pill green">Shared configuration</span>')}
 <section class="card"><div class="card-head"><h3>Route the same request through any channel</h3><span class="pill blue">Common Clocked brain</span></div><div class="grid cols4">${['VoiceIQ','Chatbot','Service Portal','Live Chat'].map(ch=>`<button class="module-tile" data-channel-jump="${ch}" style="min-height:110px"><span class="module-icon">${ch==='VoiceIQ'?'◖':ch==='Chatbot'?'◉':ch==='Service Portal'?'▤':'◎'}</span><strong>${ch}</strong><small>Evaluate the same utterance</small></button>`).join('')}</div><div class="note" style="margin-top:18px">Channels handle input and presentation. Clocked recommends choices using shared configuration, while owning modules enforce permissions, data validation and execution.</div></section>
 <div class="section-row"><div><h2>Context moves with the conversation</h2><p>Channel specific experiences should not create different business rules.</p></div></div><div class="grid cols3"><div class="card"><h3>Intent & classification</h3><p style="margin-top:10px">Ticket type, offering, category, hierarchy and supporting evidence.</p></div><div class="card"><h3>Identity & entitlement</h3><p style="margin-top:10px">Permission checks, verified profile context and appropriate access to records.</p></div><div class="card"><h3>Action with confirmation</h3><p style="margin-top:10px">Clarify, resolve, continue ticket, create request or connect to a human.</p></div></div>${notice()}`}

function renderVoice(){const recognized=state.voiceType!=='unknown';let bot='';let controls='';const existing=state.tickets.filter(x=>x.user===state.userId&&/open|progress|await/i.test(x.status));
 if(state.stage==='intro'){bot=recognized?`Hello ${esc(user().display_name)}. How can I help you today?`:'Hello. Before proceeding, could you provide your first name, last name and email address?';controls=`${button('Start call simulation','voice-start','btn')}`}
 else if(state.stage==='identify'){bot='I could not match this phone number to a registered caller. Please provide your details so we can proceed with the appropriate access checks.';controls=`<div class="formfield"><label>Sample caller name</label><input class="field" id="unknown-name" value="Sample Caller"></div><div class="formfield" style="margin-top:8px"><label>Sample email</label><input class="field" id="unknown-email" value="sample.caller@example.com"></div><div class="action-row">${button('Continue with supplied details','voice-identified','btn sm')}</div>`}
 else if(state.stage==='issue'){bot='Please tell me what is happening. I can look for guidance, find an existing ticket or prepare a new one.';controls=`<div class="formfield"><label>Caller says</label><textarea id="voice-issue" rows="2" class="field">${esc(state.utterance)}</textarea></div><div class="action-row">${button('Continue conversation','voice-analyze','btn sm')}</div>`}
 else if(state.stage==='knowledge'){const list=KB.filter(k=>k.tags.some(w=>state.utterance.toLowerCase().includes(w)));bot=list.length?`I found sample guidance about ${esc(list[0].name.toLowerCase())}. Would you like to try that before opening a ticket?`:'I could not find a verified article in this mockup. Would you like to describe your issue in more detail or open a support ticket?';controls=`<div class="choice-row">${button('Mark guidance helpful','voice-solved','btn sm')}${button('Still need help','voice-new','btn secondary sm')}</div>`}
 else if(state.stage==='clarify'){bot='Could you tell me a little more about what you need help with, so I can select the correct service?';controls=`<div class="formfield"><label>More details</label><textarea class="field" id="voice-issue" rows="2">${esc(state.utterance)}</textarea></div><div class="action-row">${button('Try again','voice-analyze','btn sm')}</div>`}
 else if(state.stage==='match'){const rel=(state.voiceType==='unknown'?[]:(state.decision?.related||[]).map(x=>x.ticket));bot=rel.length?`I found ${rel.length} potentially related ticket${rel.length>1?'s':''} from your previous support activity. Would you like to continue one or open a new ticket?`:'I did not find a matching open ticket in this demonstration. Would you like to proceed with a new ticket?';controls=`${rel.map(t=>`<button class="row-card clickable" style="width:100%;text-align:left" data-voice-ticket="${t.id}"><div><h4>${esc(t.id)} · ${esc(t.title)}</h4><p>${esc(t.status+' · '+t.channel)}</p></div><span>Continue ›</span></button>`).join('')}<div class="choice-row">${button('Create new ticket','voice-new','btn secondary sm')}</div>`}
 else if(state.stage==='after-match'){const tk=state.tickets.find(t=>t.id===state.voiceTicket);bot=`You selected ticket ${esc(tk?.id||'')}, ${esc(tk?.title||'')}. Would you like to add information or check the latest status?`;controls=`<div class="choice-row">${button('Add information','voice-add','btn sm')}${button('Check status','voice-status','btn secondary sm')}</div>`}
 else if(state.stage==='add'){bot='What additional information would you like me to add to this ticket? I will confirm it before updating the mock record.';controls=`<div class="formfield"><label>Additional details</label><textarea id="update-note" rows="3" class="field" placeholder="For example: the laptop still will not turn on after charging.">${esc(state.voiceNote||'')}</textarea></div><div class="action-row">${button('Review update','voice-review-update','btn sm')}</div>`}
 else if(state.stage==='review-update'){bot=`I will add this information to ${esc(state.voiceTicket)}: “${esc(state.voiceNote)}”. Do you confirm?`;controls=`<div class="choice-row">${button('Confirm simulated update','voice-confirm-update','btn sm')}${button('Change details','voice-add','btn ghost sm')}</div>`}
 else if(state.stage==='status'){const t=state.tickets.find(x=>x.id===state.voiceTicket);bot=`The current sample status of ticket ${esc(t?.id||'')} is ${esc(t?.status||'unknown')}. ${esc(t?.note||'No additional update.')}`;controls=`<div class="choice-row">${button('Add an update instead','voice-add','btn secondary sm')}${button('End demonstration','voice-done','btn ghost sm')}</div>`}
 else if(state.stage==='new'){const d=state.decision||evaluate(state.utterance,null);bot=d.needsAsset&&d.assets.length>1&&!state.assetId?'I see more than one device that could match your issue. Which one are you referring to?':d.selected?`Based on the description, I would propose ${esc(typeName(d.selected.ticket_type_id))}, offering ${esc(d.selected.offering_id)}: ${esc(d.selected.offering_name)}. Shall I create a simulated ticket?`:'I need a little more detail before I can recommend the correct ticket type.';controls=d.needsAsset&&d.assets.length>1&&!state.assetId?`${d.assets.map(a=>`<button class="row-card clickable" style="width:100%" data-voice-asset="${a.asset_id}"><div><h4>${esc(a.manufacturer+' '+a.model)}</h4><p>${esc(a.asset_id+' · '+a.device_label)}</p></div><span>Choose ›</span></button>`).join('')}`:`<div class="choice-row">${button('Confirm simulated ticket','voice-create','btn sm')}${button('Go back','voice-analyze','btn ghost sm')}</div>`}
 else if(state.stage==='done'){bot=state.voiceDoneMessage||'The simulated conversation has ended. No external action was taken.';controls=`${button('Restart call','voice-reset','btn secondary sm')}`}
 return `${pageHeader('VoiceIQ Simulator','CONVERSATIONAL EXPERIENCE','Experience a sample inbound call with identity recognition, cross channel ticket matching, probing questions and a visible Clocked decision trail.','<span class="pill">No real calls</span>')}
 <div class="scene-tabs"><button type="button" data-voice-type="recognized" class="scene-tab ${recognized?'active':''}">Recognized caller</button><button type="button" data-voice-type="unknown" class="scene-tab ${!recognized?'active':''}">Unrecognized caller</button></div>
 <div class="grid cols2"><section class="card"><div class="card-head"><h3>Call scenario</h3><span class="pill green">${recognized?'Caller recognized':'Identity not confirmed'}</span></div><div class="phone-panel"><div class="phone-status"><span>◖ VOICEIQ · INBOUND CALL</span><span>DEMONSTRATION</span></div><div class="bubble user">${esc(state.stage==='intro'?'Incoming call':state.utterance)}</div><div class="bubble bot">${bot}</div>${controls}</div><div class="action-row">${button('Restart','voice-reset','btn ghost sm')}${button('Open decision inspector','to-studio','btn ghost sm')}</div></section><section class="card"><div class="card-head"><h3>What Clocked is coordinating</h3><span class="pill blue">Unified context</span></div><div class="list">${['User Management','Ticket Management','Asset Management','Configured Offerings','VoiceIQ Channel'].map((x,i)=>`<div class="row-card"><div><h4>${esc(x)}</h4><p>${['Identity and permission checks','Cross channel matching and ticket status','Device context where relevant','Ticket type, category and field rules','Speak questions and read responses'][i]}</p></div><span class="tag ${i<3?'blue':''}">${i<3?'Context':'Channel'}</span></div>`).join('')}</div><div class="note" style="margin-top:14px">Before disclosing ticket details, the proposed real system must verify identity and ticket permissions. A recognized number alone is not sufficient for sensitive actions.</div></section></div>${notice()}`}

function renderFeedback(){return `${pageHeader('Share feedback','COLLABORATE AND REVIEW','Capture suggestions on Clocked decisions, business rules and module journeys. Feedback stays in this browser until exported as a JSON file.','<span class="pill">Local only</span>')}
 <div class="grid cols2"><section class="card"><h3>Leave a concept review</h3><div class="formfield" style="margin-top:16px"><label>Area of feedback</label><select class="field" id="feedback-area"><option>Overall experience</option>${MODULES.map(m=>`<option ${m.title===(state.feedbackArea||'')?'selected':''}>${m.title}</option>`).join('')}<option>Clocked decision explanations</option><option>Ticket classification</option></select></div><div class="formfield" style="margin-top:13px"><label>Your suggestion</label><textarea class="field feedback-text" id="feedback-body" placeholder="What should Clocked do differently? What feels unclear?"></textarea></div><div class="action-row">${button('Save feedback locally','save-feedback','btn')}${button('Export feedback','export-feedback','btn secondary')}</div><p class="tiny" style="margin-top:14px">No server, email or customer feedback channel is connected.</p></section><section class="card"><div class="card-head"><h3>Local feedback entries</h3><span class="pill">${state.feedback.length} saved</span></div><div class="list">${state.feedback.length?state.feedback.map((f,i)=>`<div class="flow-card"><strong>${esc(f.area)}</strong><p>${esc(f.comment)}</p><span class="flow-stamp">${esc(f.date)}</span></div>`).join(''):'<div class="empty">No feedback yet. Add a note on a decision or module behavior.</div>'}</div>${state.feedback.length?`<div class="action-row">${button('Clear local feedback','clear-feedback','btn danger sm')}</div>`:''}</section></div>${notice()}`}

function renderInspector(){const d=state.decision;let timeline=[];if(d){timeline=[['Input understood',`${esc(short(d.q,95))}`],['Identity context',`${esc(state.userId)} · ${esc(user().department)} · ${owned().length} asset${owned().length===1?'':'s'}`],['Catalog match',d.selected?`${esc(d.selected.offering_id)} · ${esc(short(d.selected.offering_name,55))}`:`No offering confirmed · ${esc(d.route)}`],['Validation',d.mm?`${esc(d.mm.category_id)} → ${esc(d.mm.subcategory_id)}`:'Clarification or knowledge path'],['Existing cases',`${d.related.length} illustrative ticket matches · across all channels`],['Recommendation',esc(short(d.rec,140))]]}
 $('inspector-body').innerHTML=`<div class="inspector-group"><div class="mini-label">Active user context</div><div class="inspector-user"><div class="avatar">${esc(state.userId.slice(-2))}</div><div><strong>${esc(user().display_name)}</strong><small>${esc(state.userId)} · ${esc(user().department)}</small></div></div><div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:12px"><span class="tag">${owned().length} devices</span><span class="tag">${esc(user().location)}</span></div></div>
 <div class="inspector-group"><div class="mini-label">Currently connected modules</div><div class="list" style="gap:6px">${['User Management','Ticket Management','Asset Management','Bot Knowledge'].map((m,i)=>`<div class="active-module ${d?'now':''}"><span>${i%2?'▤':'◈'}</span>${m}</div>`).join('')}</div></div>
 <div class="inspector-group"><div class="mini-label">Visible decision checkpoints</div>${d?`<div>${timeline.map(([t,s],i)=>`<div class="timeline-item"><div class="timeline-line"><div class="timeline-dot"></div><div class="timeline-stick"></div></div><div class="timeline-content"><strong>${t}</strong><p>${s}</p></div></div>`).join('')}</div>`:`<div class="empty" style="padding:5px 0;text-align:left;font-size:11px">Run a scenario to reveal the evidence used to recommend the next step.</div>`}</div>
 <div class="inspector-group"><div class="mini-label">Clocked API evidence</div><div class="trace-result"><strong>${state.apiStatus==='live'?'REAL CLOCKED API':state.apiStatus==='pending'?'CONTACTING CLOCKED':state.apiStatus==='error'?'API ERROR':'LOCAL DEMO'}</strong>${state.apiStatus==='live'?`<p>SDK methods: decide and rerank. Ranked offerings: ${(state.apiResult.offerings||[]).map(x=>esc(x.id)+' ('+esc(x.relevance_score)+')').join(', ')||'None selected'}</p><p>Intent result: ${esc(JSON.stringify(state.apiResult.intent||{}))}</p>`:state.apiStatus==='error'?`<p>${esc(state.apiResult?.error||'Request failed')}</p>`:`<p>${'The catalog and workflow preview remain local until a successful SDK request.'}</p>`}</div></div>
 <div class="inspector-group" style="border:0"><div class="mini-label">Decision output</div><div class="trace-result"><strong>${d?'Recommendation prepared':'Awaiting scenario'}</strong><p>${d?esc(d.rec):'Select a test case in Decision Studio, or start the VoiceIQ journey.'}</p></div><p class="tiny" style="margin-top:10px">${d?`${esc(d.source)} · ${esc(d.caseId||'Custom phrase')}`:'Source: 46 reference scenarios from the synthetic workbook'}</p></div>`;
}

function setCase(id){++liveRequestId;state.apiResult=null;state.apiStatus='not-run';const c=DB.demo_cases.find(x=>x.case_id===id);if(!c)return;state.caseId=id;state.userId=c.user_id;state.utterance=c.user_query;state.decision=null;state.assetId=null;state.step=0;render()}
function startVoice(kind='recognized'){++liveRequestId;state.apiResult=null;state.apiStatus='not-run';state.voiceType=kind;state.stage='intro';state.voiceTicket=null;state.voiceDoneMessage='';state.voiceNote='';state.decision=null;state.assetId=null;go('voice')}
function exportFeedback(){const blob=new Blob([JSON.stringify({project:'Clocked Studio Project 2',exported:new Date().toISOString(),feedback:state.feedback},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='clocked_project2_feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Local feedback exported')}

const actions={
 'to-studio':()=>go('studio'),'to-voice':()=>go('voice'),'to-tickets':()=>go('tickets'),
 'open-t003':()=>{setCase('T003');state.decision=evaluate(state.utterance,getCase());state.step=0;go('studio')},
 'voice-existing':()=>{setCase('T003');state.decision=evaluate(state.utterance,getCase());startVoice('recognized')},
 'voice-current':()=>{state.stage='intro';state.voiceType='recognized';go('voice')},
 'run-decision':doEvaluate,'next-step':()=>{state.step=Math.min(3,state.step+1);render()},'previous-step':()=>{state.step=Math.max(0,state.step-1);render()},'reset-decision':()=>{state.decision=null;state.apiResult=null;state.apiStatus='not-run';render()},
 'toggle-assets':()=>{state.showAllAssets=!state.showAllAssets;render()},
 'find-users':()=>{state.searchUsers=$('user-search').value.trim();render()},
 'search-catalog':()=>{state.searchCatalog=$('catalog-search').value.trim();render()},
 'voice-start':()=>{state.stage=state.voiceType==='unknown'?'identify':'issue';render()},
 'voice-identified':()=>{state.stage='issue';render()},
 'voice-analyze':()=>{const field=$('voice-issue');if(field)state.utterance=field.value;state.decision=evaluate(state.utterance,getCase());state.stage=/KNOWLEDGE/.test(state.decision.route)?'knowledge':(['CLARIFY','OUT_OF_SCOPE'].includes(state.decision.route)?'clarify':state.voiceType==='unknown'?'new':'match');if(state.voiceType==='unknown')notify('Existing ticket details remain private until identity is verified');render()},
 'voice-new':()=>{state.stage='new';render()},
 'voice-solved':()=>{state.stage='done';state.voiceDoneMessage='Guidance marked as helpful for this simulation. No real action was taken.';render()},
 'voice-add':()=>{state.stage='add';render()},
 'voice-status':()=>{state.stage='status';render()},
 'voice-review-update':()=>{state.voiceNote=$('update-note')?.value.trim()||'';if(!state.voiceNote){notify('Please add a short update');return}state.stage='review-update';render()},
 'voice-confirm-update':()=>{const t=state.tickets.find(x=>x.id===state.voiceTicket);if(t)t.note=state.voiceNote;state.voiceDoneMessage=`The information was added to the simulated ticket ${state.voiceTicket}. No real ticket was changed.`;state.stage='done';render()},
 'voice-create':()=>{const d=state.decision||evaluate(state.utterance,getCase());const id='SIM'+String(state.tickets.length+1001);state.tickets.unshift({id,user:state.userId,title:short(state.utterance,68),issue:state.utterance,status:'Open',channel:'VoiceIQ',owner:'Simulated Support Queue',date:'Nov 11, 2026',note:'Concept only. No external ticket created.',kind:typeName(d.selected?.ticket_type_id)});state.voiceDoneMessage=`Simulated ticket ${id} was created for this walkthrough. No real ticket or external record was created.`;state.stage='done';render()},
 'voice-done':()=>{state.stage='done';state.voiceDoneMessage='The demonstration is complete. No external action was taken.';render()},
 'voice-reset':()=>startVoice(state.voiceType),
 'handoff':()=>{notify('Simulated handoff prepared. No agent was contacted.');state.decision=state.decision||evaluate(state.utterance,getCase());render()},
 'save-feedback':()=>{const comment=$('feedback-body')?.value.trim();if(!comment){notify('Please enter feedback first');return}state.feedback.unshift({area:$('feedback-area').value,comment,date:new Date().toLocaleString()});try{localStorage.setItem('clocked_p2_feedback',JSON.stringify(state.feedback))}catch(e){}notify('Saved in this browser');render()},
 'clear-feedback':()=>{state.feedback=[];try{localStorage.removeItem('clocked_p2_feedback')}catch(e){}render()},
 'export-feedback':exportFeedback
};
$('main-nav').addEventListener('click',e=>{const btn=e.target.closest('[data-page]');if(btn)go(btn.dataset.page)});
$('feedback-shortcut').addEventListener('click',()=>go('feedback'));
$('main').addEventListener('click',e=>{
 const g=e.target.closest('[data-go]');if(g){go(g.dataset.go);return}
 const r=e.target.closest('[data-action]');if(r){const name=r.dataset.action;if(name.startsWith('asset:')){state.assetId=name.slice(6);if(state.decision)state.decision=evaluate(state.utterance,getCase());notify('Asset selected for the current scenario');render();return}actions[name]?.();return}
 const step=e.target.closest('[data-step]');if(step){state.step=Number(step.dataset.step);render();return}
 const row=e.target.closest('[data-user-row]');if(row){state.userId=row.dataset.userRow;state.decision=null;notify('Shared user context changed');render();return}
 const catalog=e.target.closest('[data-catalog]');if(catalog){state.catalogId=catalog.dataset.catalog;render();return}
 const vtype=e.target.closest('[data-voice-type]');if(vtype){startVoice(vtype.dataset.voiceType);return}
 const vticket=e.target.closest('[data-voice-ticket]');if(vticket){state.voiceTicket=vticket.dataset.voiceTicket;state.stage='after-match';render();return}
 const vasset=e.target.closest('[data-voice-asset]');if(vasset){state.assetId=vasset.dataset.voiceAsset;if(state.decision)state.decision=evaluate(state.utterance,getCase());notify('Device selected');render();return}
 const channel=e.target.closest('[data-channel-jump]');if(channel){state.channel=channel.dataset.channelJump;state.decision=evaluate(state.utterance,getCase());state.step=0;go('studio');return}
});
$('main').addEventListener('change',e=>{
 if(e.target.id==='scenario'){setCase(e.target.value)}
 else if(e.target.id==='demo-user'||e.target.id==='asset-user'){state.userId=e.target.value;state.decision=null;render()}
 else if(e.target.id==='channel'){state.channel=e.target.value;state.decision=null;render()}
 else if(e.target.id==='ticket-filter'){state.ticketFilter=e.target.value;render()}
});
$('main').addEventListener('input',e=>{
 
 if(e.target.id==='utterance')state.utterance=e.target.value;
 if(e.target.id==='user-search')state.searchUsers=e.target.value;
 if(e.target.id==='catalog-search')state.searchCatalog=e.target.value;
});
render();
